"""gs_runtime.py -- runtime library for programs generated by the GameScript compiler.

Generated modules do `from gs_runtime import *` and end with `main(G)`.

Modes
  python3 prog.py                      headless: simulate 60 frames, print the log
  python3 prog.py --frames 200         simulate more frames
  python3 prog.py --keys "3:SPACE,9:LEFT"   press keys on given frames (headless)
  python3 prog.py --pygame             open a window (needs `pip install pygame`)

Frame order (Game.step):  ON START of new entities -> key events -> ON UPDATE
                          -> collisions (ON COLLISION WITH) -> RULEs -> cleanup
Collisions are edge-triggered: the handler runs once when two entities start
overlapping (16x16 boxes), and again only after they separated and met again.
Screen coordinates: x grows to the right, y grows DOWNWARD (so UP means y - n).
"""

import sys
import argparse

BOX = 16                      # collision box size in pixels
__all__ = ["Vec2", "Entity", "Game", "main", "gs_str"]


def gs_str(v):
    """Text of a value as PRINT shows it."""
    if v is True:
        return "TRUE"
    if v is False:
        return "FALSE"
    return str(v)


class Vec2:
    """Immutable 2D vector (the VECTOR2 type)."""
    __slots__ = ("x", "y")

    def __init__(self, x=0.0, y=0.0):
        object.__setattr__(self, "x", float(x))
        object.__setattr__(self, "y", float(y))

    def __setattr__(self, name, value):
        raise AttributeError("VECTOR2 components are read-only")

    def __add__(self, o):
        return Vec2(self.x + o.x, self.y + o.y)

    def __sub__(self, o):
        return Vec2(self.x - o.x, self.y - o.y)

    def __mul__(self, k):
        return Vec2(self.x * k, self.y * k)

    def __eq__(self, o):
        return isinstance(o, Vec2) and self.x == o.x and self.y == o.y

    def __ne__(self, o):
        return not self.__eq__(o)

    def __hash__(self):
        return hash((self.x, self.y))

    def __str__(self):
        return "VECTOR2(%s, %s)" % (gs_str(self.x), gs_str(self.y))

    __repr__ = __str__


class Entity:
    """Base class of every generated E_<Name> class."""
    NAME = "?"
    PROPS = ["position"]
    COLLISIONS = {}           # target entity name -> handler method name
    KEYS = {}                 # key name -> handler method name

    def __init__(self, game, pos=None):
        self.game = game
        self.position = pos if pos is not None else Vec2(0, 0)
        self.alive = True
        self.in_death = False
        self.uid = game.next_uid()

    def move(self, direction, amount):
        dx, dy = {"UP": (0, -1), "DOWN": (0, 1), "LEFT": (-1, 0), "RIGHT": (1, 0)}[direction]
        self.position = Vec2(self.position.x + dx * amount, self.position.y + dy * amount)

    # event hooks, overridden by generated classes
    def on_start(self):
        pass

    def on_update(self):
        pass

    def on_death(self):
        pass

    def describe(self):
        parts = []
        for name in self.PROPS:
            attr = "position" if name == "position" else "p_" + name
            parts.append("%s=%s" % (name, gs_str(getattr(self, attr))))
        return "%s: %s" % (self.NAME, " ".join(parts))


def _overlap(a, b):
    return abs(a.position.x - b.position.x) < BOX and abs(a.position.y - b.position.y) < BOX


class Game:
    def __init__(self, name):
        self.name = name
        self.classes = []
        self.defaults = {}        # entity name -> its default instance
        self.entities = []        # live instances (default + spawned)
        self.rules = []
        self.pending_starts = []
        self.active = set()       # collision pairs currently overlapping
        self.state = "PLAYING"    # PLAYING | WON | LOST
        self.frame = 0
        self.uid = 0
        self.use_pygame = False

    # ---- setup (called by generated code) ----
    def next_uid(self):
        self.uid += 1
        return self.uid

    def register(self, cls):
        self.classes.append(cls)

    def add_rule(self, name, fn):
        self.rules.append((name, fn))

    def init_defaults(self):
        for cls in self.classes:
            self.defaults[cls.NAME] = self._create(cls, Vec2(0, 0))

    # ---- operations used by compiled statements ----
    def _create(self, cls, pos):
        e = cls(self, pos)
        self.entities.append(e)
        self.pending_starts.append(e)
        return e

    def spawn(self, cls, pos):
        return self._create(cls, pos)

    def ref(self, name):
        return self.defaults[name]

    def destroy(self, e):
        if not e.alive or e.in_death:
            return
        e.in_death = True
        e.on_death()
        e.alive = False

    def print(self, value):
        print(gs_str(value))

    def play_sound(self, filename):
        if self.use_pygame:
            try:
                import pygame
                pygame.mixer.Sound(filename).play()
                return
            except Exception:
                pass
        print("[sound] %s" % filename)

    def win(self):
        if self.state == "PLAYING":
            self.state = "WON"
            print("*** YOU WIN (frame %d) ***" % self.frame)

    def lose(self):
        if self.state == "PLAYING":
            self.state = "LOST"
            print("*** GAME OVER (frame %d) ***" % self.frame)

    # ---- the game loop ----
    def _flush_starts(self):
        while self.pending_starts:
            e = self.pending_starts.pop(0)
            if e.alive:
                e.on_start()

    def _collisions(self):
        live = [e for e in self.entities if e.alive]
        now = set()
        for i, a in enumerate(live):
            for b in live[i + 1:]:
                if not _overlap(a, b):
                    continue
                key = (a.uid, b.uid)
                now.add(key)
                if key in self.active:
                    continue
                h = a.COLLISIONS.get(b.NAME)
                if h and a.alive and b.alive:
                    getattr(a, h)(b)
                h = b.COLLISIONS.get(a.NAME)
                if h and a.alive and b.alive:
                    getattr(b, h)(a)
        self.active = now

    def step(self, keys=()):
        if self.state != "PLAYING":
            return
        self.frame += 1
        self._flush_starts()
        for key in keys:
            for e in list(self.entities):
                h = e.KEYS.get(key)
                if h and e.alive:
                    getattr(e, h)()
        self._flush_starts()          # entities spawned by key handlers start before updating
        for e in list(self.entities):
            if e.alive:
                e.on_update()
        self._collisions()
        for _name, fn in self.rules:
            if self.state != "PLAYING":
                break
            fn()
        self.entities = [e for e in self.entities if e.alive]

    # ---- reporting ----
    def dump(self):
        print("-- game '%s': %s after %d frame(s)" % (self.name, self.state, self.frame))
        for cls in self.classes:
            e = self.defaults[cls.NAME]
            print("   %s%s" % (e.describe(), "" if e.alive else "  [destroyed]"))
        extra = [e for e in self.entities if e not in self.defaults.values()]
        if extra:
            print("   + %d spawned instance(s) alive" % len(extra))


# ---------------------------------------------------------------- run modes

def parse_key_script(text):
    """'3:SPACE,5:LEFT' -> {3: ['SPACE'], 5: ['LEFT']}"""
    script = {}
    for item in filter(None, (t.strip() for t in text.split(","))):
        frame, key = item.split(":")
        script.setdefault(int(frame), []).append(key.strip().upper())
    return script


def run_headless(game, frames, script):
    try:
        for n in range(1, frames + 1):
            if game.state != "PLAYING":
                break
            game.step(script.get(n, ()))
    except ZeroDivisionError:
        print("runtime error: division by zero (frame %d)" % game.frame)
        game.state = "ERROR"
    game.dump()


def run_pygame(game, fps=60):
    import pygame
    game.use_pygame = True
    pygame.init()
    try:
        pygame.mixer.init()
    except Exception:
        pass
    screen = pygame.display.set_mode((640, 480))
    pygame.display.set_caption("GameScript - " + game.name)
    font = pygame.font.SysFont(None, 18)
    big = pygame.font.SysFont(None, 56)
    clock = pygame.time.Clock()
    names = {"return": "ENTER", "escape": "ESCAPE", "space": "SPACE",
             "up": "UP", "down": "DOWN", "left": "LEFT", "right": "RIGHT"}

    def color(name):
        h = sum(ord(c) * (i + 3) for i, c in enumerate(name))
        return (80 + h * 37 % 170, 80 + h * 91 % 170, 80 + h * 53 % 170)

    running = True
    while running:
        keys = []
        for ev in pygame.event.get():
            if ev.type == pygame.QUIT:
                running = False
            elif ev.type == pygame.KEYDOWN:
                k = pygame.key.name(ev.key)
                keys.append(names.get(k, k.upper()))
        try:
            game.step(keys)
        except ZeroDivisionError:
            print("runtime error: division by zero")
            game.state = "ERROR"
        screen.fill((20, 22, 30))
        for e in game.entities:
            p = e.position
            pygame.draw.rect(screen, color(e.NAME), (int(p.x), int(p.y), BOX, BOX))
            screen.blit(font.render(e.NAME, True, (230, 230, 230)), (int(p.x), int(p.y) - 14))
        if game.state != "PLAYING":
            msg = {"WON": "YOU WIN", "LOST": "GAME OVER"}.get(game.state, game.state)
            surf = big.render(msg, True, (255, 255, 255))
            screen.blit(surf, surf.get_rect(center=(320, 240)))
        pygame.display.flip()
        clock.tick(fps)
    pygame.quit()
    game.dump()


def main(game, argv=None):
    ap = argparse.ArgumentParser(description="GameScript program: " + game.name)
    ap.add_argument("--frames", type=int, default=60, help="frames to simulate (headless)")
    ap.add_argument("--keys", default="", help='key script, e.g. "3:SPACE,5:LEFT"')
    ap.add_argument("--pygame", action="store_true", help="open a window instead of headless")
    args = ap.parse_args(argv)
    if args.pygame:
        run_pygame(game)
    else:
        run_headless(game, args.frames, parse_key_script(args.keys))
